// src/js/Chat/Emoji/EmojiParser.js
import { applyEmojiFallback } from "../E/EmojiFallback.js";

/**
 * Processa texto e aplica fallback apenas quando necessário.
 */
export function emojify(text) {
  if (!text) return "";

  // Não convertemos tudo para Twemoji. Apenas fallback.
  return applyEmojiFallback(text);
}
